def masks(L,R,O):
 for name,X in [('R',R),('L',L)]:
  for t in ['id','rot90','rot180','rot270','flipx','flipy','transpose','anti']:
   f={'id':lambda x:x,'rot90':lambda x:np.rot90(x,1),'rot180':lambda x:np.rot90(x,2),'rot270':lambda x:np.rot90(x,3),'flipx':lambda x:np.fliplr(x),'flipy':lambda x:np.flipud(x),'transpose':lambda x:x.T,'anti':lambda x:np.rot90(x.T,2)}[t]
   Xf=f(X)
   for op, y in [('and', L & Xf),('xor',L^Xf),('RnotL',Xf & ~L),('LnotR',L&~Xf),('or',L|Xf)]:
    if np.array_equal(y,O): print(name,t,op)
for z in [(L1,R1,O1),(L2,R2,O2)]: masks(*z)
